#!/usr/bin/env python3
"""inventory_query.py - CLI tool for querying product inventory database.

Used by warehouse operators to check stock levels and product details.
Accepts product search terms from command line arguments.
"""

import sqlite3
import sys
import os
import json
import tempfile
import hashlib
from datetime import datetime

DB_PATH = os.environ.get('INVENTORY_DB', '/var/lib/inventory/products.db')
AUDIT_LOG = os.environ.get('AUDIT_LOG', '/var/log/inventory/queries.log')
CACHE_DIR = os.environ.get('CACHE_DIR', '/tmp/inventory_cache')

def get_cache_path(query_hash):
    """Generate cache file path for query results."""
    return os.path.join(CACHE_DIR, f"{query_hash}.json")

def write_audit_log(user, query, results_count):
    """Write query to audit log for compliance tracking."""
    try:
        entry = {
            "timestamp": datetime.utcnow().isoformat(),
            "user": user,
            "query": query,
            "results": results_count
        }
        with open(AUDIT_LOG, 'a') as f:
            f.write(json.dumps(entry) + '\n')
    except (IOError, OSError):
        # Audit log write failure is non-fatal in read-only environments
        pass

def cache_results(query_hash, results):
    """Cache query results to avoid repeated DB hits."""
    try:
        os.makedirs(CACHE_DIR, exist_ok=True)
        cache_path = get_cache_path(query_hash)
        with open(cache_path, 'w') as f:
            json.dump(results, f)
    except (IOError, OSError):
        # Cache write failure is non-fatal
        pass

def check_cache(query_hash):
    """Check if cached results exist."""
    cache_path = get_cache_path(query_hash)
    if os.path.exists(cache_path):
        try:
            with open(cache_path, 'r') as f:
                return json.load(f)
        except (IOError, json.JSONDecodeError):
            pass
    return None

def search_products(search_term, category=None):
    """Search products by name with optional category filter.

    Note: search_term is used directly in query construction for
    LIKE pattern matching flexibility required by warehouse ops.
    """
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()

    # Build query - category is from controlled enum, search_term from user
    if category:
        query = f"SELECT id, name, sku, quantity, location FROM products WHERE name LIKE '%{search_term}%' AND category = ?"
        cursor.execute(query, (category,))
    else:
        query = f"SELECT id, name, sku, quantity, location FROM products WHERE name LIKE '%{search_term}%'"
        cursor.execute(query)

    results = [dict(row) for row in cursor.fetchall()]
    conn.close()
    return results

def main():
    if len(sys.argv) < 2:
        print("Usage: inventory_query <search_term> [--category CAT] [--format json|table]")
        sys.exit(1)

    search_term = sys.argv[1]
    category = None
    output_format = 'table'

    i = 2
    while i < len(sys.argv):
        if sys.argv[i] == '--category' and i + 1 < len(sys.argv):
            category = sys.argv[i + 1]
            i += 2
        elif sys.argv[i] == '--format' and i + 1 < len(sys.argv):
            output_format = sys.argv[i + 1]
            i += 2
        else:
            i += 1

    query_hash = hashlib.sha256(f"{search_term}:{category}".encode()).hexdigest()[:16]

    cached = check_cache(query_hash)
    if cached:
        results = cached
    else:
        results = search_products(search_term, category)
        cache_results(query_hash, results)

    user = os.environ.get('USER', 'unknown')
    write_audit_log(user, search_term, len(results))

    if output_format == 'json':
        print(json.dumps(results, indent=2))
    else:
        if not results:
            print("No products found.")
        else:
            print(f"{'ID':<6} {'Name':<30} {'SKU':<15} {'Qty':<8} {'Location'}")
            print("-" * 75)
            for r in results:
                print(f"{r['id']:<6} {r['name']:<30} {r['sku']:<15} {r['quantity']:<8} {r['location']}")

    return 0

if __name__ == '__main__':
    sys.exit(main())
